#include "user_config.hpp"
#include "gilbert.hpp"
#include "sdesc.hpp"
struct UserModel {
 UserConfig u;FFT fft;std::array<std::vector<std::array<double,2>>,6>K;unsigned long calls=0;
#ifdef LF_TWO_OWNER
 LocalFieldTeam team;
#endif
 UserModel(UserConfig info,const std::filesystem::path&kernel):u(std::move(info)),fft(u.px,u.py){std::ifstream f(kernel,std::ios::binary);std::vector<std::array<double,6>>raw(fft.n);f.read((char*)raw.data(),raw.size()*sizeof(raw[0]));if(!f||f.peek()!=EOF)throw std::runtime_error("kernel shape");for(int a=0;a<6;a++){std::vector<double>v(fft.n);for(int j=0;j<fft.n;j++){v[j]=-raw[j][a];if(!std::isfinite(v[j]))throw std::runtime_error("kernel finite");}K[a]=fft.fwd(v);}}
 Evaluation eval(const Spins&m){
  C cc=u.c;cc.m=m;
#ifdef LF_TWO_OWNER
  std::lock_guard<std::mutex>call(team.model_call_mutex());auto f=team.evaluate_owned(cc);
#else
  auto f=evaluate(cc,false);
#endif
  calls++;Evaluation v;v.H=std::move(f.H);v.Eparts={f.E[0]-f.Ecross,f.Ecross,f.E[1],f.E[2],f.E[3],0,0};auto&c=u.c;std::vector<V>M(c.count);for(size_t j=0;j<c.count;j++)M[j]=(m[0][j]*c.Ms[0]+m[1][j]*c.Ms[1])*.5;
  std::array<std::vector<std::array<double,2>>,3>s;for(int a=0;a<3;a++){std::vector<double>x(fft.n);for(int y=0;y<c.n[1];y++)for(int k=0;k<c.n[0];k++)x[k+y*u.px]=M[k+y*c.n[0]][a];s[a]=fft.fwd(x);}v.Hd.resize(c.count);int lut[3][3]={{0,3,4},{3,1,5},{4,5,2}};
  for(int a=0;a<3;a++){std::vector<std::array<double,2>>x(fft.nf);for(int j=0;j<fft.nf;j++)for(int b=0;b<3;b++){auto k=K[lut[a][b]][j],q=s[b][j];x[j][0]+=k[0]*q[0]-k[1]*q[1];x[j][1]+=k[0]*q[1]+k[1]*q[0];}auto real=fft.inv(x);for(int y=0;y<c.n[1];y++)for(int k=0;k<c.n[0];k++)v.Hd[k+y*c.n[0]][a]=real[k+y*u.px];}
  for(int i=0;i<2;i++){v.p[i].resize(c.count);for(size_t j=0;j<c.count;j++){v.H[i][j]+=v.Hd[j]+u.external;auto ph=project(m[i][j],v.H[i][j]);v.p[i][j]=ph*(GAMMA_SD/2);v.residual=std::max(v.residual,norm(ph));}}
  for(size_t j=0;j<c.count;j++){v.Eparts[5]-=.5*mu0*c.volume*dot(M[j],v.Hd[j]);v.Eparts[6]-=mu0*c.volume*dot(M[j],u.external);}for(double e:v.Eparts)v.E+=e;if(!std::isfinite(v.E))throw std::runtime_error("energy nonfinite");return v;
 }
};
struct UserState {SD s;unsigned long dynamic_steps=0;double origin=0,LA=0,LB=0,L=0;};
void write_cp(const std::filesystem::path&p,const UserState&x,const C&c,const std::string&id){auto tmp=p;tmp+=".tmp";std::ofstream f(tmp,std::ios::binary);auto put=[&](const auto&v){f.write((const char*)&v,sizeof(v));};std::uint64_t magic=0x3150435245535546ULL,n=c.count,len=id.size();put(magic);put(n);put(len);f.write(id.data(),id.size());for(int q:c.n)put(q);put(x.dynamic_steps);for(double q:{x.origin,x.LA,x.LB,x.L,x.s.aux,x.s.dt})put(q);for(int q:{x.s.updates,x.s.resets,x.s.stable})put(q);for(auto*arr:{&x.s.m,&x.s.prev,&x.s.Gprev})for(int i=0;i<2;i++)for(size_t j=0;j<c.count;j++){V v=(*arr)[i].empty()?V{}:(*arr)[i][j];put(v.x);put(v.y);put(v.z);}f.flush();if(!f)throw std::runtime_error("CP write");f.close();std::filesystem::rename(tmp,p);}
UserState read_cp(const std::filesystem::path&p,const C&c,const std::string&id){std::ifstream f(p,std::ios::binary);auto get=[&](auto&v){f.read((char*)&v,sizeof(v));if(!f)throw std::runtime_error("CP truncated");};std::uint64_t magic,n,len;get(magic);get(n);get(len);if(magic!=0x3150435245535546ULL||n!=c.count||len!=id.size())throw std::runtime_error("CP schema/shape");std::string stored(len,' ');f.read(stored.data(),len);if(stored!=id)throw std::runtime_error("CP physics/numerics identity");for(int q:c.n){int a;get(a);if(a!=q)throw std::runtime_error("CP grid");}UserState x;get(x.dynamic_steps);for(double*p:{&x.origin,&x.LA,&x.LB,&x.L,&x.s.aux,&x.s.dt}){get(*p);if(!std::isfinite(*p))throw std::runtime_error("CP finite");}for(int*p:{&x.s.updates,&x.s.resets,&x.s.stable})get(*p);if(x.s.updates<0||x.s.resets<0||x.s.stable<0||x.LA<0||x.LB<0||x.L<0||x.s.dt<MIN_SD||x.s.dt>MAX_SD)throw std::runtime_error("CP controls");for(auto*arr:{&x.s.m,&x.s.prev,&x.s.Gprev})for(auto&sub:*arr){sub.resize(n);for(auto&v:sub){get(v.x);get(v.y);get(v.z);if(!finite(v))throw std::runtime_error("CP vector");}}if(f.peek()!=EOF)throw std::runtime_error("CP trailing");for(auto&sub:x.s.m)for(auto v:sub)if(std::abs(norm(v)-1)>1e-12)throw std::runtime_error("CP unit");return x;}
Spins user_rhs(const Spins&m,const Evaluation&e,const UserConfig&u){Spins out=m;for(int i=0;i<2;i++)for(size_t j=0;j<m[i].size();j++){if(!finite(m[i][j])||!finite(e.H[i][j]))throw std::runtime_error("nonfinite stage/field");out[i][j]=gilbert(m[i][j],e.H[i][j],u.gamma[i]/GAMMA_SD,u.alpha[i]);if(!finite(out[i][j]))throw std::runtime_error("nonfinite RHS");}return out;}
std::array<double,2>power(const Spins&m,const Evaluation&e,const UserConfig&u){std::array<double,2>d{};for(int i=0;i<2;i++){long double sum=0;for(size_t j=0;j<m[i].size();j++){auto a=m[i][j],b=e.H[i][j];V cross={a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};sum+=dot(cross,cross);}d[i]=static_cast<double>(sum)*mu0*u.c.volume*u.c.Ms[i]*u.gamma[i]*u.alpha[i]/(2*(1+u.alpha[i]*u.alpha[i]));if(!std::isfinite(d[i])||d[i]<0)throw std::runtime_error("power invalid");}return d;}
std::array<double,2>residual(const Spins&m,const Evaluation&e){std::array<double,2>v{};for(int i=0;i<2;i++)for(size_t j=0;j<m[i].size();j++)v[i]=std::max(v[i],norm(project(m[i][j],e.H[i][j])));return v;}
#ifndef FIM_USER_LIBRARY
int main(int argc,char**argv){std::filesystem::path out;unsigned long started_fields=0;try{
 if(argc!=11)throw std::runtime_error("CONFIG KERNEL STATE OUTPUT dynamic|static|static_fresh STEPS TOL SAVE_EVERY ID seed|checkpoint");auto u=read_user(argv[1]);out=argv[4];if(std::filesystem::exists(out))throw std::runtime_error("output exists");std::filesystem::create_directories(out);std::string phase=argv[5],id=argv[9];int limit=std::stoi(argv[6]),save=std::stoi(argv[8]);double tol=std::stod(argv[7]);if((phase!="dynamic"&&phase!="static"&&phase!="static_fresh")||limit<0||save<1||tol<=0||!std::isfinite(tol)||id.size()!=64)throw std::runtime_error("user arguments");
 UserState x;if(std::string(argv[10])=="checkpoint")x=read_cp(argv[3],u.c,id);else if(std::string(argv[10])=="seed"){std::ifstream f(argv[3],std::ios::binary);for(auto&sub:x.s.m){sub.resize(u.c.count);f.read((char*)sub.data(),sub.size()*sizeof(V));}if(!f||f.peek()!=EOF)throw std::runtime_error("seed size");for(auto&sub:x.s.m)for(auto v:sub)if(!finite(v)||std::abs(norm(v)-1)>1e-12)throw std::runtime_error("seed unit");}else throw std::runtime_error("state kind");
 if(phase=="static_fresh"){SD s;s.m=std::move(x.s.m);x.s=std::move(s);}auto begin=Clock::now();auto guard=[&]{if(std::chrono::duration<double>(Clock::now()-begin).count()>u.wall||rss()>u.c.memory)throw std::runtime_error("resource_budget_exhausted");};UserModel model(u,argv[2]);
 auto eval=[&](const Spins&m){guard();if(started_fields>=u.fields)throw std::runtime_error("field_budget_exhausted");started_fields++;{std::ofstream f(out/"counter.json");f<<"{\"started_fields\":"<<started_fields<<"}\n";}auto e=model.eval(m);guard();return e;};auto current=eval(x.s.m);if(std::string(argv[10])=="seed")x.origin=current.E;
 std::ofstream hist(out/"history.csv");hist<<std::setprecision(17)<<"dynamic_steps,static_updates,time_s,energy_J,loss_A_J,loss_B_J,total_loss_J,defect_J,residual_A_Apm,residual_B_Apm,fields\n";
 unsigned long cp_steps=x.dynamic_steps;int cp_updates=x.s.updates;auto persist=[&](bool frame){if(frame){cp_steps=x.dynamic_steps;cp_updates=x.s.updates;}auto v=residual(x.s.m,current);hist<<x.dynamic_steps<<','<<x.s.updates<<','<<x.dynamic_steps*u.dt<<','<<current.E<<','<<x.LA<<','<<x.LB<<','<<x.L<<','<<current.E-x.origin+x.L<<','<<v[0]<<','<<v[1]<<','<<started_fields<<'\n';hist.flush();auto tmp=out/"progress.json.tmp";std::ofstream f(tmp);f<<std::setprecision(17)<<"{\"phase\":\""<<phase<<"\",\"dynamic_steps\":"<<x.dynamic_steps<<",\"static_updates\":"<<x.s.updates<<",\"time_ps\":"<<x.dynamic_steps*u.dt*1e12<<",\"energy_J\":"<<current.E<<",\"residual_A_Apm\":"<<v[0]<<",\"residual_B_Apm\":"<<v[1]<<",\"loss_A_J\":"<<x.LA<<",\"loss_B_J\":"<<x.LB<<",\"total_loss_J\":"<<x.L<<",\"fields\":"<<started_fields<<",\"checkpoint_dynamic_steps\":"<<cp_steps<<",\"checkpoint_static_updates\":"<<cp_updates<<",\"checkpoint_time_ps\":"<<cp_steps*u.dt*1e12<<",\"elapsed_s\":"<<std::chrono::duration<double>(Clock::now()-begin).count()<<"}\n";f.close();std::filesystem::rename(tmp,out/"progress.json");if(frame){write_cp(out/"checkpoint.bin",x,u.c,id);snapshot(out/("m_"+std::to_string(phase=="dynamic"?x.dynamic_steps:x.s.updates)+".bin"),x.s.m);}};
 persist(true);
 auto initial=out/"initial";std::filesystem::create_directory(initial);snapshot(initial/"final.bin",x.s.m);save_eval(initial,"final",current);auto ir=residual(x.s.m,current);{std::ofstream f(initial/"result.json");f<<std::setprecision(17)<<"{\"residual_A_Apm\":"<<ir[0]<<",\"residual_B_Apm\":"<<ir[1]<<"}\n";}
 std::string stop;
 if(phase=="dynamic"){
 if(x.dynamic_steps>static_cast<unsigned long>(limit))throw std::runtime_error("resume beyond target");while(x.dynamic_steps<static_cast<unsigned long>(limit)){
  auto&m=x.s.m;auto e1=eval(m);auto k1=user_rhs(m,e1,u);auto d1=power(m,e1,u);auto s2=add(m,k1,u.dt/2);auto e2=eval(s2);auto k2=user_rhs(s2,e2,u);auto d2=power(s2,e2,u);auto s3=add(m,k2,u.dt/2);auto e3=eval(s3);auto k3=user_rhs(s3,e3,u);auto d3=power(s3,e3,u);auto s4=add(m,k3,u.dt);auto e4=eval(s4);auto k4=user_rhs(s4,e4,u);auto d4=power(s4,e4,u);Spins next=m;for(int i=0;i<2;i++)for(size_t j=0;j<m[i].size();j++){next[i][j]+=(k1[i][j]+k2[i][j]*2+k3[i][j]*2+k4[i][j])*(u.dt/6);double n=std::hypot(next[i][j].x,next[i][j].y,next[i][j].z);if(!finite(next[i][j])||!std::isfinite(n)||n==0)throw std::runtime_error("nonfinite dynamic");auto q=next[i][j];next[i][j]={q.x/n,q.y/n,q.z/n};}auto end=eval(next);double inc=0;for(int i=0;i<2;i++){double q=(d1[i]+2*d2[i]+2*d3[i]+d4[i])*u.dt/6;if(i==0)x.LA+=q;else x.LB+=q;inc+=q;}x.L+=inc;if(!std::isfinite(x.L))throw std::runtime_error("nonfinite loss");x.s.m=std::move(next);current=std::move(end);x.dynamic_steps++;persist(x.dynamic_steps%save==0);
 }stop="physical_time";
 }else{
 while(true){auto v=residual(x.s.m,current);if(v[0]<=tol&&v[1]<=tol){stop="residual_tolerance";break;}if(x.s.updates>=limit){stop="step_budget";break;}auto next=x.s;auto g=gradient_sd(next.m,current.H);BB b;if(next.updates)b=bb_sd(next.m,g,next.prev,next.Gprev);next.dt=next.updates?choose_sd(b,next.updates,next.resets):MIN_SD;next.prev=next.m;next.Gprev=std::move(g);for(int i=0;i<2;i++)for(size_t j=0;j<next.m[i].size();j++)next.m[i][j]=rational_sd(next.m[i][j],current.H[i][j],next.dt,u.c.Ms[i]);auto end=eval(next.m);next.updates++;next.aux+=next.dt;x.s=std::move(next);current=std::move(end);persist(x.s.updates%save==0);
 }}
 persist(true);snapshot(out/"final.bin",x.s.m);save_eval(out,"final",current);auto v=residual(x.s.m,current);std::ofstream result(out/"result.json");result<<std::setprecision(17)<<"{\"stop_reason\":\""<<stop<<"\",\"dynamic_steps\":"<<x.dynamic_steps<<",\"static_updates\":"<<x.s.updates<<",\"energy_J\":"<<current.E<<",\"origin_J\":"<<x.origin<<",\"loss_A_J\":"<<x.LA<<",\"loss_B_J\":"<<x.LB<<",\"total_loss_J\":"<<x.L<<",\"residual_A_Apm\":"<<v[0]<<",\"residual_B_Apm\":"<<v[1]<<",\"fields\":"<<started_fields<<",\"wall_s\":"<<std::chrono::duration<double>(Clock::now()-begin).count()<<"}\n";return 0;
 }catch(const std::exception&e){if(!out.empty()&&std::filesystem::exists(out)){std::ofstream f(out/"failure.json");f<<"{\"status\":\"failed\",\"fields_started\":"<<started_fields<<"}\n";std::ofstream(out/"failure.txt")<<e.what();}std::cerr<<e.what()<<'\n';return 2;}}

#endif // FIM_USER_LIBRARY
